def open_holes_to_exterior(mask_bool):
    """Cut a narrow channel from each interior hole to the exterior.

    A donut final mask would have its hole filled by the exterior polygon,
    swallowing pixels owned by another cell. Cutting a 2px slit makes the
    shape simply connected so the exterior polygon matches the mask.
    """
    if mask_bool is None or mask_bool.size == 0 or int(mask_bool.sum()) == 0:
        return mask_bool
    H, W = mask_bool.shape
    bg = (~mask_bool).astype(np.uint8)
    num, labels, _, _ = cv2.connectedComponentsWithStats(bg, connectivity=8)
    if num <= 1:
        return mask_bool
    border = set(np.unique(np.concatenate([labels[0, :], labels[-1, :], labels[:, 0], labels[:, -1]])))
    out = mask_bool.copy()
    for lbl in range(1, num):
        if lbl in border:
            continue
        ys_, xs_ = np.where(labels == lbl)
        if len(xs_) == 0:
            continue
        cy = int(np.median(ys_))
        cx = int(np.median(xs_))
        # Search 4 directions for the shortest path to exterior background.
        best = None  # (length, direction)
        # east
        for direction in ("e", "w", "s", "n"):
            length = None
            if direction == "e":
                for x in range(cx, W):
                    if int(labels[cy, x]) in border:
                        length = x - cx
                        break
            elif direction == "w":
                for x in range(cx, -1, -1):
                    if int(labels[cy, x]) in border:
                        length = cx - x
                        break
            elif direction == "s":
                for y in range(cy, H):
                    if int(labels[y, cx]) in border:
                        length = y - cy
                        break
            else:
                for y in range(cy, -1, -1):
                    if int(labels[y, cx]) in border:
                        length = cy - y
                        break
            if length is not None and (best is None or length < best[0]):
                best = (length, direction)
        if best is None:
            continue
        _, direction = best
        if direction == "e":
            x_end = cx
            for x in range(cx, W):
                if int(labels[cy, x]) in border:
                    x_end = x
                    break
            else:
                x_end = W - 1
            y_lo, y_hi = max(0, cy - 1), min(H, cy + 1)
            out[y_lo:y_hi, cx:x_end + 1] = False
        elif direction == "w":
            x_start = cx
            for x in range(cx, -1, -1):
                if int(labels[cy, x]) in border:
