def erode_for_polygon(mask_bool):
    """One 3x3 erosion margin so fillPoly re-rasterization cannot overlap neighbours."""
    if mask_bool is None or mask_bool.size == 0:
        return mask_bool
    if int(mask_bool.sum()) < 60:
        return mask_bool
    u8 = mask_bool.astype(np.uint8)
    er = cv2.erode(u8, np.ones((3, 3), np.uint8), iterations=1)
    er = largest_connected_component(er.astype(bool))
    if int(er.sum()) < 10:
        return mask_bool
    return er


